  var len = bytes[1];
  if (bytes.length !== len + 3) throw new Error('FRAME: length mismatch');
  var x = 0;
  for (var j = 1; j < len + 2; j++) x ^= bytes[j];
  if ((x & 0xff) !== bytes[len + 2]) throw new Error('CHECKSUM: mismatch');
  if (len < 2) throw new Error('FRAME: payload too short');
  var p = bytes.slice(2, 2 + len);
  var status = p[0];
  if (status !== 0) throw new Error('device error ' + errorName(status));
  var op = p[1];
  if (op === 0x10) {
    if (len < 7) throw new Error('FRAME: step reply too short');
    return {
      applied: [s16(p[2], p[3]) / 10000, s16(p[4], p[5]) / 10000],
      limited: (p[6] & 1) === 1
    };
  }
  if (op === 0x20) {
    if (len < 4) throw new Error('FRAME: lift reply too short');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('ARGUMENT: bad lift position');
    return {
      applied: {op: 'lift', position: p[2] === 1 ? 'up' : 'down'},
      limited: (p[3] & 1) === 1
    };
  }
  if (op === 0x21) {
    if (len < 4) throw new Error('FRAME: grip reply too short');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('ARGUMENT: bad grip state');
    return {
      applied: {op: 'grip', state: p[2] === 1 ? 'closed' : 'open'},
      limited: (p[3] & 1) === 1
    };
  }
  if (op === 0x01) {
    if (len < 5) throw new Error('FRAME: hello reply too short');
    var model = '';
    for (var k = 6; k < len; k++) model += String.fromCharCode(p[k]);
    return {
      applied: null,
      limited: false,
      hello: {protocolVersion: p[2], channels: p[3], maxStep: s16(p[4], p[5]) / 10000, model: model}
    };
  }
  throw new Error('OPCODE: unexpected reply opcode ' + op);
}
